#include <iostream>
#include <algorithm>
using namespace std;

long long total_moves = 0;

int countDigitsInNumber(long long n) {
    int count = 0;
    while (n > 0) {
        n /= 10;
        count++;
    }
    return count;
}

long long getNumberThreshold(long long n) {
    int digits = countDigitsInNumber(n);
    long long threshold = 0, base_power = 1;
    for (int i = 0; i < digits; i++) {
        threshold += base_power;
        base_power *= 10;
    }
    if (threshold <= n) return threshold;
    return (threshold - 1) / 10;
}

long long recursiveProcess(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base_num = getNumberThreshold(n);
    long long limit = base_num * 10 + 1;
    if (n % base_num == 0) {
        long long quotient = n / base_num;
        if (n <= limit / 2 + base_num) return countDigitsInNumber(base_num) * quotient;
        else {
            long long diff = recursiveProcess(limit - n);
            return countDigitsInNumber(limit) + diff;
        }
    } else {
        long long lower_bound = (n / base_num) * base_num;
        long long upper_bound = (n / base_num + 1) * base_num;
        long long res = recursiveProcess(lower_bound) + recursiveProcess(n - lower_bound);
        if (n > limit / 2) {
            res = min(recursiveProcess(lower_bound) + recursiveProcess(n - lower_bound),
                      countDigitsInNumber(limit) + recursiveProcess(limit - n));
        }
        return res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << recursiveProcess(n) << endl;
    return 0;
}
